                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = rule.getDescription();
            String existingFileName = storedRules.getProperty(indexDescription);
            if (violations.isEmpty() && existingFileName == null && integrityMode == IntegrityMode.REPAIR) {
                return;
            }

            String strategyFileName = ruleViolationFileNameStrategy.createRuleFileName(description);
            if (strategyFileName == null || strategyFileName.isEmpty()) {
                throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
            }
            String ruleFileName = existingFileName == null ? strategyFileName : existingFileName;

            if (violations.isEmpty() && existingFileName != null && integrityMode == IntegrityMode.REPAIR) {
                forgetRule(indexDescription, ruleFileName);
                return;
            }

            Path ruleFile = writableRuleFile(ruleFileName);
            byte[] previousContents = null;
            boolean existed = lexists(ruleFile);
            if (existed && !Files.isSymbolicLink(ruleFile) && Files.isRegularFile(ruleFile, LinkOption.NOFOLLOW_LINKS)) {
                try {
