+    private boolean storeUpdateAllowed;
+    private IntegrityMode integrityMode;
+    private File storeFolder;
+    private Path storeFolderPath;
+    private Path storeFolderRealPath;
+    private Path storedRulesPath;
+    private FileSyncedProperties storedRules;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        configuredRuleViolationFileNameStrategy = null;
+        customFileNameStrategy = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new NullPointerException("ruleViolationFileNameStrategy must not be null");
+        }
+        configuredRuleViolationFileNameStrategy = ruleViolationFileNameStrategy;
+        customFileNameStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        RuleViolationFileNameStrategy fileNameStrategy = createFileNameStrategy(properties);
+        String path = properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT);
+
+        storeFolder = new File(path);
+        storeFolderPath = storeFolder.toPath().toAbsolutePath().normalize();
+        storedRulesPath = storeFolderPath.resolve(STORED_RULES_FILE_NAME);
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesPath);
+
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        prepareFolderAndIndex();
+        storeFolderRealPath = realPathOf(storeFolderPath, "store folder");
+
+        FileSyncedProperties candidate = getOrCreateStoredRules(storedRulesPath);
+        synchronized (candidate) {
+            boolean indexExists = lexists(storedRulesPath);
+            if (!indexExists) {
+                // Delaying creation is observable and intentional.  In fail mode
+                // a bad folder must not acquire an index as a side effect.
+                candidate.loadEmpty(storedRulesPath.toFile());
+            } else {
+                candidate.loadExisting(storedRulesPath.toFile());
+            }
+
+            if (integrityMode == IntegrityMode.IGNORE) {
+                if (!indexExists) {
+                    candidate.syncFileSystem();
+                }
+            } else {
+                IntegrityAnalysis analysis = analyze(candidate, fileNameStrategy);
+                if (integrityMode == IntegrityMode.FAIL) {
+                    if (analysis.hasProblems()) {
+                        throw new StoreInitializationFailedException(analysis.failureMessage());
+                    }
+                    if (!indexExists) {
+                        candidate.syncFileSystem();
+                    }
+                } else {
+                    repair(candidate, analysis);
+                    if (!indexExists || analysis.changed) {
+                        candidate.syncFileSystem();
+                    }
+                }
+            }
+        }
+
+        ruleViolationFileNameStrategy = fileNameStrategy;
+        storedRules = candidate;
+    }
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+
+    private IntegrityMode parseIntegrity(String value) {
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s '%s'; accepted values are '%s', '%s' and '%s'",
+                INTEGRITY_PROPERTY_NAME, value, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+    }
+
+    private RuleViolationFileNameStrategy createFileNameStrategy(Properties properties) {
+        String configuredName = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (customFileNameStrategy) {
+            if (configuredName != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return configuredRuleViolationFileNameStrategy;
+        }
+        if (configuredName == null || FILE_NAMES_RANDOM.equals(configuredName)) {
+            return __ -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configuredName)) {
+            return new DescriptionRuleViolationFileNameStrategy();
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configuredName);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            return (RuleViolationFileNameStrategy) strategyClass.getConstructor().newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s'; use '%s', '%s', or a class with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, configuredName, FILE_NAMES_RANDOM, FILE_NAMES_DESCRIPTION), e);
+        }
+    }
+
+    private void prepareFolderAndIndex() {
+        boolean indexExists = lexists(storedRulesPath);
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        try {
+            if (!Files.exists(storeFolderPath, LinkOption.NOFOLLOW_LINKS)) {
+                if (!storeFolderPath.toFile().mkdirs() && !Files.isDirectory(storeFolderPath)) {
+                    throw new IOException("Could not create store folder");
+                }
+            }
+            if (!Files.isDirectory(storeFolderPath)) {
+                throw new IOException("Store path is not a directory");
+            }
+            if (indexExists && !Files.isRegularFile(storedRulesPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("The index is not a regular file directly in the store folder");
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot initialize violation store at %s", storedRulesPath), e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(Path path) {
+        try {
+            String key = path.toFile().getCanonicalPath();
+            return STORED_RULES_BY_PATH.computeIfAbsent(key, ignored -> new FileSyncedProperties(path.toFile()));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private static boolean lexists(Path path) {
+        try {
+            return Files.exists(path, LinkOption.NOFOLLOW_LINKS) || Files.isSymbolicLink(path);
+        } catch (SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (violations.isEmpty() && existingFileName == null && integrityMode == IntegrityMode.REPAIR) {
+                return;
+            }
+
+            String strategyFileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+            if (strategyFileName == null || strategyFileName.isEmpty()) {
+                throw new StoreUpdateFailedException("RuleViolationFileNameStrategy returned no file name");
+            }
+            String ruleFileName = existingFileName == null ? strategyFileName : existingFileName;
+
+            if (violations.isEmpty() && existingFileName != null && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(description, ruleFileName);
+                return;
+            }
+
+            Path ruleFile = writableRuleFile(ruleFileName);
+            byte[] previousContents = null;
+            boolean existed = lexists(ruleFile);
+            if (existed && !Files.isSymbolicLink(ruleFile) && Files.isRegularFile(ruleFile, LinkOption.NOFOLLOW_LINKS)) {
+                try {
+                    previousContents = Files.readAllBytes(ruleFile);
+                } catch (IOException e) {
+                    throw new StoreUpdateFailedException(e);
+                }
+            }
+
+            write(violations, ruleFile);
+            if (existingFileName == null) {
+                storedRules.setProperty(description, ruleFileName);
+                try {
+                    storedRules.syncFileSystem();
+                } catch (RuntimeException e) {
+                    storedRules.remove(description);
+                    rollbackFile(ruleFile, existed, previousContents);
+                    throw e;
+                }
+            }
+        }
+    }
+
+    private Path writableRuleFile(String ruleFileName) {
+        Path ruleFile = pathForName(ruleFileName);
+        if (ruleFile == null || !isDirectChild(ruleFile)) {
+            throw new StoreUpdateFailedException("Rule violation file name does not name a file directly in the store folder");
+        }
+
+        try {
+            if (lexists(ruleFile)) {
+                if (sameFile(ruleFile, storedRulesPath)) {
+                    throw new StoreUpdateFailedException("Rule violation file name leads to the stored.rules index");
+                }
+                if (!Files.isRegularFile(ruleFile)) {
+                    throw new StoreUpdateFailedException("Rule violation file name does not lead to a regular file");
+                }
+                if (!realPathOf(ruleFile, "rule violation file").getParent().equals(storeFolderRealPath)) {
+                    throw new StoreUpdateFailedException("Rule violation file name leads outside the store folder");
+                }
+            } else if (!ruleFile.getParent().equals(storeFolderPath)) {
+                throw new StoreUpdateFailedException("Rule violation file name leads outside the store folder");
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        return ruleFile;
+    }
+
+    private void write(List<String> violations, Path ruleDetails) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        try {
+            Files.write(ruleDetails, builder.toString().getBytes(UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException | SecurityException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void rollbackFile(Path ruleFile, boolean existed, byte[] previousContents) {
+        try {
+            if (existed && previousContents != null) {
+                Files.write(ruleFile, previousContents, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+            } else if (!existed) {
+                deleteNamedFile(ruleFile, false);
+            }
+        } catch (IOException e) {
+            log.warn("Could not roll back violation file {}", ruleFile, e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storedRules) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (violationsText.replace("\r", "").replace("\n", "").isEmpty()) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        Path file = pathForName(fileName);
+        if (file == null) {
+            throw new StoreReadException(new InvalidPathException(String.valueOf(fileName), "invalid path"));
+        }
+        try {
+            String result = new String(toByteArray(file.toFile()), UTF_8);
+            return result.replace("\r\n", "\n");
+        } catch (IOException | SecurityException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private Path pathForName(String fileName) {
+        if (fileName == null) {
+            return null;
+        }
+        try {
+            return storeFolderPath.resolve(fileName);
+        } catch (InvalidPathException | NullPointerException e) {
+            return null;
+        }
+    }
+
+    private boolean isDirectChild(Path path) {
+        return path != null && storeFolderPath.equals(path.getParent());
+    }
+
+    private Path realPathOf(Path path, String description) {
+        try {
+            return path.toRealPath();
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException("Cannot resolve " + description + " " + path, e);
+        }
+    }
+
+    private boolean sameFile(Path first, Path second) throws IOException {
+        if (!lexists(first) || !lexists(second)) {
+            return first.normalize().equals(second.normalize());
+        }
+        return Files.isSameFile(first, second);
+    }
+
+    private IntegrityAnalysis analyze(FileSyncedProperties properties, RuleViolationFileNameStrategy strategy) {
+        List<IntegrityEntry> entries = new ArrayList<>();
+        for (Map.Entry<String, String> property : properties.entries()) {
+            IntegrityEntry entry = new IntegrityEntry(property.getKey(), property.getValue(), pathForName(property.getValue()));
+            entry.direct = isDirectChild(entry.path);
+            entry.regular = entry.direct && entry.path != null && Files.isRegularFile(entry.path);
+            entry.broken = !entry.regular;
+            if (entry.regular) {
+                entry.resolved = readLines(property.getValue()).isEmpty();
+            }
+            entry.derivedName = strategy.createRuleFileName(entry.description);
+            if (entry.derivedName == null || entry.derivedName.isEmpty()) {
+                throw new StoreInitializationFailedException("RuleViolationFileNameStrategy returned no file name");
+            }
+            entry.derivedPath = pathForName(entry.derivedName);
+            entry.misplaced = !entry.name.equals(entry.derivedName);
+        }
+
+        markShared(entries);
+        markCollisionsAndOccupied(entries);
+        List<Path> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityAnalysis(entries, unownedFiles);
+    }
+
+    private void markShared(List<IntegrityEntry> entries) {
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                IntegrityEntry first = entries.get(i);
+                IntegrityEntry second = entries.get(j);
+                boolean shared = first.name.equals(second.name);
+                if (!shared && first.regular && second.regular) {
+                    try {
+                        shared = Files.isSameFile(first.path, second.path);
+                    } catch (IOException | SecurityException e) {
+                        throw new StoreInitializationFailedException(e);
+                    }
+                }
+                if (shared) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+    }
+
+    private void markCollisionsAndOccupied(List<IntegrityEntry> entries) {
+        Map<String, List<IntegrityEntry>> byDerivedName = new HashMap<>();
+        for (IntegrityEntry entry : entries) {
+            byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<IntegrityEntry> collidingEntries : byDerivedName.values()) {
+            if (collidingEntries.size() > 1) {
+                for (IntegrityEntry entry : collidingEntries) {
+                    entry.colliding = true;
+                }
+            }
+        }
+
+        Set<String> recordedNames = new HashSet<>();
+        for (IntegrityEntry entry : entries) {
+            recordedNames.add(entry.name);
+        }
+        for (IntegrityEntry entry : entries) {
+            if (entry.name.equals(entry.derivedName)) {
+                continue;
+            }
+            boolean occupied = recordedNames.contains(entry.derivedName);
+            if (!occupied) {
+                Path derivedPath = entry.derivedPath;
+                occupied = derivedPath == null || !isDirectChild(derivedPath) || lexists(derivedPath);
+            }
+            entry.occupied = occupied;
+        }
+    }
+
+    private List<Path> findUnownedFiles(List<IntegrityEntry> entries) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
+            for (Path file : files) {
+                if (STORED_RULES_FILE_NAME.equals(file.getFileName().toString())
+                        || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (IntegrityEntry entry : entries) {
+                    if (entry.regular && Files.isSameFile(entry.path, file)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file);
+                }
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(path -> path.getFileName().toString()));
+        return result;
+    }
+
+    private void repair(FileSyncedProperties properties, IntegrityAnalysis analysis) {
+        for (IntegrityEntry entry : analysis.entriesSorted()) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+                analysis.changed = true;
+            } else if (entry.resolved) {
+                deleteNamedFileForRepair(entry.path);
+                properties.remove(entry.description);
+                analysis.changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveNamedFile(entry.path, entry.derivedPath);
+                properties.setProperty(entry.description, entry.derivedName);
+                analysis.changed = true;
+            }
+        }
+    }
+
+    private void moveNamedFile(Path source, Path destination) {
+        if (samePathAsIndex(source) || samePathAsIndex(destination)) {
+            throw new StoreInitializationFailedException("Integrity repair would move the stored.rules index");
+        }
+        try {
+            Path sourceToMove = source;
+            boolean sourceIsLink = Files.isSymbolicLink(source);
+            if (sourceIsLink) {
+                sourceToMove = source.toRealPath();
+            }
+            Files.move(sourceToMove, destination, StandardCopyOption.REPLACE_EXISTING);
+            if (sourceIsLink) {
+                Files.deleteIfExists(source);
+            }
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not move misplaced violation file %s to %s", source, destination), e);
+        }
+    }
+
+    private void deleteNamedFileForRepair(Path path) {
+        if (samePathAsIndex(path)) {
+            return;
+        }
+        try {
+            deleteNamedFile(path, true);
+        } catch (IOException | SecurityException e) {
+            throw new StoreInitializationFailedException("Could not delete resolved violation file " + path, e);
+        }
+    }
+
+    private void forgetRule(String description, String ruleFileName) {
+        Path ruleFile = pathForName(ruleFileName);
+        boolean shared = isSharedWithAnotherRule(description, ruleFile);
+        if (!shared) {
+            if (ruleFile == null || samePathAsIndex(ruleFile)) {
+                throw new StoreUpdateFailedException("Cannot delete the stored rule file");
+            }
+            try {
+                deleteNamedFile(ruleFile, true);
+            } catch (IOException | SecurityException e) {
+                throw new StoreUpdateFailedException(e);
+            }
+        }
+        storedRules.remove(description);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedWithAnotherRule(String description, Path ruleFile) {
+        for (Map.Entry<String, String> property : storedRules.entries()) {
+            if (property.getKey().equals(description)) {
+                continue;
+            }
+            if (property.getValue().equals(pathFileName(ruleFile))) {
+                return true;
+            }
+            Path other = pathForName(property.getValue());
+            if (ruleFile != null && other != null) {
+                try {
+                    if (lexists(ruleFile) && lexists(other) && Files.isSameFile(ruleFile, other)) {
+                        return true;
+                    }
+                } catch (IOException | SecurityException e) {
+                    throw new StoreUpdateFailedException(e);
+                }
+            }
+        }
+        return false;
+    }
+
+    private String pathFileName(Path path) {
+        return path == null || path.getFileName() == null ? null : path.getFileName().toString();
+    }
+
+    private boolean samePathAsIndex(Path path) {
+        if (path == null) {
+            return false;
+        }
+        try {
+            return sameFile(path, storedRulesPath);
+        } catch (IOException | SecurityException e) {
+            return path.normalize().equals(storedRulesPath.normalize());
+        }
+    }
+
+    private void deleteNamedFile(Path path, boolean deleteSymbolicLinkTarget) throws IOException {
+        if (!lexists(path)) {
+            return;
+        }
+        if (deleteSymbolicLinkTarget && Files.isSymbolicLink(path)) {
+            Path target = path.toRealPath();
+            Files.delete(target);
+            Files.deleteIfExists(path);
+        } else {
+            Files.delete(path);
+        }
+    }
+
+    private enum IntegrityMode { IGNORE, REPAIR, FAIL }
+
+    private static final class IntegrityEntry {
+        final String description;
+        final String name;
+        final Path path;
+        Path derivedPath;
+        String derivedName;
+        boolean direct;
+        boolean regular;
+        boolean broken;
+        boolean resolved;
+        boolean shared;
+        boolean misplaced;
+        boolean colliding;
+        boolean occupied;
+
+        IntegrityEntry(String description, String name, Path path) {
+            this.description = description;
+            this.name = name;
+            this.path = path;
+        }
+    }
+
+    private static final class IntegrityAnalysis {
+        final List<IntegrityEntry> entries;
+        final List<Path> unownedFiles;
+        boolean changed;
+
+        IntegrityAnalysis(List<IntegrityEntry> entries, List<Path> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        boolean hasProblems() {
+            for (IntegrityEntry entry : entries) {
+                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
+                    return true;
+                }
+            }
+            return !unownedFiles.isEmpty();
+        }
+
+        List<IntegrityEntry> entriesSorted() {
+            List<IntegrityEntry> result = new ArrayList<>(entries);
+            result.sort(Comparator.comparing(entry -> entry.description));
+            return result;
+        }
+
+        String failureMessage() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed");
+            appendEntries(result, "broken entries", entries, entry -> entry.broken);
+            appendEntries(result, "resolved entries", entries, entry -> entry.resolved);
+            appendEntries(result, "shared entries", entries, entry -> entry.shared);
+            appendFiles(result, "unowned files", unownedFiles);
+            appendEntries(result, "misplaced entries", entries, entry -> entry.misplaced);
+            appendEntries(result, "colliding entries", entries, entry -> entry.colliding);
+            appendEntries(result, "occupied entries", entries, entry -> entry.occupied);
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String heading, List<IntegrityEntry> all,
+                                   EntryCondition condition) {
+            List<IntegrityEntry> matching = all.stream().filter(condition::matches)
+                    .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
+            if (!matching.isEmpty()) {
+                result.append('\n').append(heading).append(':');
+                for (IntegrityEntry entry : matching) {
+                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.name);
+                }
+            }
+        }
+
+        private void appendFiles(StringBuilder result, String heading, List<Path> files) {
+            if (!files.isEmpty()) {
+                result.append('\n').append(heading).append(':');
+                for (Path file : files) {
+                    result.append("\n  ").append(file.getFileName());
+                }
+            }
+        }
+
+        @FunctionalInterface
+        private interface EntryCondition {
+            boolean matches(IntegrityEntry entry);
+        }
